mapper.sql:
and (
copywriting.user_id = #{actorUserId}
or exists ( select 1 from t_copywriting_expert_assignment scope_expert_assignment inner join t_user scope_expert on scope_expert.user_id = scope_expert_assignment.expert_user_id and coalesce(scope_expert.status, 0) = 0 where scope_expert_assignment.account_user_id = copywriting.user_id and scope_expert_assignment.expert_user_id = #{actorUserId} and exists ( select 1 from t_user_role_map scope_expert_role_map inner join t_role scope_expert_role on scope_expert_role.role_id = scope_expert_role_map.role_id where scope_expert_role_map.user_id = #{actorUserId} and upper(scope_expert_role.name) = 'EXPERT' ) )
or exists ( select 1 from t_copywriting_organization_admin_assignment scope_org_assignment inner join t_user scope_org_admin on scope_org_admin.user_id = scope_org_assignment.admin_user_id and coalesce(scope_org_admin.status, 0) = 0 where scope_org_assignment.account_user_id = copywriting.user_id and scope_org_assignment.admin_user_id = #{actorUserId} and exists ( select 1 from t_user_role_map scope_org_role_map inner join t_role scope_org_role on scope_org_role.role_id = scope_org_role_map.role_id where scope_org_role_map.user_id = #{actorUserId} and upper(scope_org_role.name) = 'ORG_ADMIN' ) )
)

